// SPDX-License-Identifier: MIT
pragma solidity >=0.8.13;

import {
    IERC1155MetadataURI
} from "@openzeppelin/contracts/token/ERC1155/extensions/IERC1155MetadataURI.sol";

import {IERC1155Singleton} from "../../erc1155/interfaces/IERC1155Singleton.sol";

